for m,pts in d.items():
 x=[p[0] for p in pts]; y=[p[1] for p in pts]; xm=sum(x)/len(x); ym=sum(y)/len(y); b=sum((a-xm)*(c-ym) for a,c in pts)/sum((a-xm)**2 for a in x); a=ym-b*xm; ss=sum((c-ym)**2 for c in y); rr=sum((c-(a+b*z))**2 for z,c in pts); print(m,len(pts),b,a,1-rr/ss)\""

